-- Re-applied after a worker restart (same idempotent SQL as 20261016111244; inserts nothing the
-- second time). Kept so the files match supabase_migrations.schema_migrations.
-- C-071b batch 1: 106 more five-star hotels, the next 4 per city by luxury rank
-- (Tripadvisor's typical minimum price among hotels with 200+ reviews; scripts/catalog/batch.ts),
-- now that Workers Paid prices hundreds of hotels a day (B-023, C-151). Google Hotels ids
-- (DataForSEO Hotel Searches in the hotel's country, checked by name and distance) let Price Drops
-- get exact quotes (C-148); photos are the hotels' own via LiteAPI (D-51), self-hosted in
-- apps/web/public/hotels. Idempotent: an existing slug or Tripadvisor key is skipped.
insert into public.hotels
  (slug, name, city_id, lat, lng, xotelo_key, liteapi_id, dfs_hotel_identifier, image_url,
   image_credit, image_source_url, active)
select v.slug, v.name, c.id, v.lat, v.lng, v.xotelo_key,
       case when exists (select 1 from public.hotels h where h.liteapi_id = v.liteapi_id)
            then null else v.liteapi_id end,
       v.dfs, v.image_url,
       v.image_credit, v.image_source_url, true
